import {bindOriginPicker} from '/src/ui/origin-picker.mjs';
import {motionPreference} from '/src/ui/motion-preference.mjs';
import {openCanvasArcPicker} from '/src/range-overlay/arc-picker-foundry.mjs';
import {bindCrewControls} from '/src/vehicle-crew-foundry.mjs';
const choices=[],motionValues=[];
globalThis.game={user:{isGM:true},actors:new Map()};
globalThis.canvas={app:{canvas:{getBoundingClientRect:()=>({left:0,top:0,width:1200,height:1000})},renderer:{screen:{width:1200,height:1000}}},stage:{scale:{x:1},worldTransform:{apply:p=>p}}};
const fixture=globalThis.a11yFixture={choices,motionValues,sheetOpens:0};
const entries=picker=>Array.from(picker.querySelectorAll('[data-document-id]'),b=>({id:b.dataset.documentId,name:b.querySelector('strong').textContent}));
fixture.bind=()=>document.querySelectorAll('[data-origin-picker]').forEach(picker=>bindOriginPicker(picker,entries(picker)));
fixture.bind();
document.addEventListener('click',event=>{const b=event.target.closest('[data-document-id],[data-homebrew-choice]');if(b)choices.push({id:b.dataset.documentId,homebrew:b.hasAttribute('data-homebrew-choice')});});
fixture.stopMotion=motionPreference.subscribe(value=>motionValues.push(value));
const token=id=>({id,name:id,w:50,h:80,center:{x:800,y:650},actor:{type:'vehicle'},document:{rotation:0}});
document.querySelector('#arcs').onclick=()=>openCanvasArcPicker({source:token('Attacker'),target:token('Target'),selection:{},preview:selection=>({pool:{ability:2},range:{lineOfSight:'clear',label:'Close'},poolLabel:'2 Ability',attack:{itemName:'Laser'},error:!selection.defenseZone?"Choose the target's agreed defence zone":""}),commit:value=>{fixture.committed=value;},cancel:()=>{fixture.cancelled=true;}});
const member={sheet:{render:()=>fixture.sheetOpens++},testUserPermission:()=>true};
const root=document.querySelector('#crew');root.innerHTML='<div data-crew-sheet data-crew-token="pilot" tabindex="0">Pilot character sheet</div><button type="button" class="sf-crew-portrait" data-crew-token="all">Crew</button>';
const scene={id:'crew-scene'},crewToken={id:'pilot',actor:member,parent:scene,flags:{'star-wars-ffg':{aboard:{vehicleId:'ship',seat:'crew',roles:['pilot']}}}};
scene.tokens=Object.assign([crewToken],{get:id=>id==='pilot'?crewToken:null});
bindCrewControls(root,{id:'ship',parent:scene});
fixture.denyCrew=deny=>{game.user.isGM=!deny;member.testUserPermission=()=>!deny;};
globalThis.foundry={applications:{api:{HandlebarsApplicationMixin:base=>base,DialogV2:{}},sheets:{ActorSheetV2:class{_onRender(){}},ItemSheetV2:class{}}}};
const {StarWarsActorSheet}=await import('/src/sheets.mjs');
const sheet=new StarWarsActorSheet();sheet.element=document.createElement('section');sheet.actor={};sheet.onDrop=event=>{event.preventDefault();fixture.drops++;};fixture.drops=0;
fixture.repeatSheetRender=()=>{for(let i=0;i<200;i++)sheet._onRender({themeKey:'edge'},{});sheet.element.dispatchEvent(new Event('drop',{bubbles:true,cancelable:true}));};
fixture.ready=true;
